package paxos

import "errors"

// Ballot is a totally-ordered proposal number. Node id breaks ties so that
// ballots generated by different proposers never collide.
type Ballot struct {
	N    uint64
	Node int
}

func (b Ballot) Greater(o Ballot) bool {
	if b.N != o.N {
		return b.N > o.N
	}
	return b.Node > o.Node
}

func (b Ballot) Less(o Ballot) bool { return o.Greater(b) }

// Operation kinds applied to the replicated state machine.
const (
	OpNoop = "noop" // fills log holes; never mutates state
	OpSet  = "set"
	OpDel  = "del"
)

// Op is a single state-machine command.
type Op struct {
	Kind  string
	Key   string
	Value string
}

// LogEntry is one replicated log slot. Slots may be sparse (holes) until a
// leader repairs them.
type LogEntry struct {
	Slot   uint64
	Ballot Ballot
	Op     Op
}

// ---- wire messages ----

// PrepareReq is Phase 1a. From is the first slot the proposer cares about
// (its commitIndex+1); the acceptor replies with everything it knows from
// that slot upward so the proposer can repair holes.
type PrepareReq struct {
	Ballot Ballot
	From   uint64
}

// PrepareResp is Phase 1b (Promise).
type PrepareResp struct {
	Ok       bool
	Promised Ballot
	Entries  map[uint64]LogEntry // accepted entries with Slot >= From
	MaxSlot  uint64
}

// AcceptReq is Phase 2a.
type AcceptReq struct {
	Ballot Ballot
	Entry  LogEntry
}

// AcceptResp is Phase 2b (Accepted).
type AcceptResp struct {
	Ok       bool
	Promised Ballot
}

// CommitNotice tells a follower that a slot was chosen by a majority.
type CommitNotice struct {
	Slot uint64
}

// SnapshotMsg carries a snapshot of the state machine to a follower that
// fell behind the leader's compacted log (InstallSnapshot-style catch-up).
type SnapshotMsg struct {
	Index uint64
	State map[string]string
}

var (
	ErrNotLeader   = errors.New("paxos: not leader (or lease expired)")
	ErrNoMajority  = errors.New("paxos: failed to reach a majority")
	ErrUnreachable = errors.New("paxos: peer unreachable")
)
